require_once __DIR__.'/../../includes/db.php';require_once __DIR__.'/../includes/auth.php';require_login();$id=(int)($_GET['id']??0);$st=$conn->prepare('SELECT * FROM customers WHERE id=?');$st->bind_param('i',$id);$st->execute();$c=$st->get_result()->fetch_assoc();if(!$c){set_flash('error','Customer not found.');redirect_to('backend/customers/index.php');}
$st=$conn->prepare('SELECT s.*,car.car_name,car.plate_number,IFNULL(p.paid,0) paid FROM car_sales s JOIN cars car ON car.id=s.car_id LEFT JOIN(SELECT sale_id,SUM(amount) paid FROM sale_payments GROUP BY sale_id)p ON p.sale_id=s.id WHERE s.customer_id=? ORDER BY s.sale_date DESC');$st->bind_param('i',$id);$st->execute();$sales=$st->get_result();
$st=$conn->prepare('SELECT l.*,c.car_name FROM leads l LEFT JOIN cars c ON c.id=l.car_id WHERE l.customer_id=? ORDER BY l.created_at DESC');$st->bind_param('i',$id);$st->execute();$leads=$st->get_result();
$page_title='Customer Details';include __DIR__.'/../includes/header.php';include __DIR__.'/../includes/leftsidebar.php';?>
<div class="content-page"><div class="report-title"><h1 class="page-title"><?=e($c['name'])?></h1><a class="btn btn-dark" href="index.php">Back</a></div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(280px,1fr))"><div class="card"><h2>Contact</h2><p><strong>Phone:</strong> <?=e($c['phone']?:'—')?></p><p><strong>Email:</strong> <?=e($c['email']?:'—')?></p><p><strong>ID:</strong> <?=e($c['national_id']?:'—')?></p><p><strong>Address:</strong> <?=e($c['address']?:'—')?></p></div><div class="card"><h2>Relationship</h2><p><strong>Type:</strong> <?=e($c['customer_type'])?></p><p><strong>Source:</strong> <?=e($c['source']?:'—')?></p><p><strong>Notes:</strong> <?=e($c['notes']?:'—')?></p></div></div><div class="card"><h2>Purchase History</h2><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Car</th><th>Sale</th><th>Paid</th><th>Balance</th><th></th></tr></thead><tbody><?php while($s=$sales->fetch_assoc()):?><tr><td><?=e($s['sale_date'])?></td><td><?=e($s['car_name'].' / '.$s['plate_number'])?></td><td><?=money($s['sale_price'])?></td><td><?=money($s['paid'])?></td><td><?=money(max(0,$s['sale_price']-$s['paid']))?></td><td><a class="btn" href="../sales/receipt.php?id=<?=$s['id']?>">Receipt</a></td></tr><?php endwhile;?></tbody></table></div></div><div class="card"><h2>Lead History</h2><div class="table-responsive"><table class="table"><thead><tr><th>Created</th><th>Interested Car</th><th>Stage</th><th>Next Follow-up</th></tr></thead><tbody><?php while($l=$leads->fetch_assoc()):?><tr><td><?=e($l['created_at'])?></td><td><?=e($l['car_name']?:'General enquiry')?></td><td><?=e($l['lead_stage'])?></td><td><?=e($l['next_follow_up']?:'—')?></td></tr><?php endwhile;?></tbody></table></div></div></div><?php include __DIR__.'/../includes/footer.php';?>
